def erreur_moyenne(points, a, b):
    total = 0
    for distance, prix in points:
        prediction = a * distance + b
        total += abs(prix - prediction)
    return round(total / len(points), 1)

def plus_proche(point, exemples):
    meilleure_distance = None
    meilleure_etiquette = None
    for x, y, etiquette in exemples:
        d = (x - point[0]) ** 2 + (y - point[1]) ** 2
        if meilleure_distance is None or d < meilleure_distance:
            meilleure_distance = d
            meilleure_etiquette = etiquette
    return meilleure_etiquette

def neurone(entrees, poids, seuil):
    somme = 0
    for i in range(len(entrees)):
        somme += entrees[i] * poids[i]
    if somme >= seuil:
        return 1
    return 0
